                  {tab.count}
                </span>
              </div>
            ))}
          </div>

          {/* Active campaigns list */}
          <div
            style={{
              background: "#FFFFFF",
              border: `1px solid ${BRAND.border}`,
              borderRadius: 10,
              overflow: "hidden",
            } as React.CSSProperties}
          >
            {campaigns.map((campaign, i) => (
              <div
                key={i}
                style={{
                  padding: "16px 18px",
                  borderTop: i === 0 ? "none" : `1px solid ${BRAND.borderSoft}`,
                } as React.CSSProperties}
              >
                {/* Top row */}
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 8,
                    marginBottom: 4,
                  } as React.CSSProperties}
                >
                  <span
                    style={{
                      fontFamily: FONT.sans,
                      fontSize: 14,
                      fontWeight: 700,
                      color: BRAND.onyx,
                      flex: 1,
                    } as React.CSSProperties}
                  >
                    {campaign.title}
                  </span>
                  <span
                    style={{
                      fontFamily: FONT.sans,
                      fontSize: 9,
                      fontWeight: 700,
                      color: BRAND.sage,
                      background: BRAND.sageSoft,
                      padding: "2px 6px",
                      borderRadius: 100,
                      letterSpacing: "0.06em",
                    } as React.CSSProperties}
                  >
                    LIVE
                  </span>
                  <span
                    style={{
                      fontFamily: FONT.sans,
                      fontSize: 11,
                      color: BRAND.stone,
                    } as React.CSSProperties}
                  >
                    {campaign.stats.map(s => `${s.value} ${s.label.toLowerCase()}`).slice(0, 2).join(" · ")}
                  </span>
                </div>

                {/* Sub */}
                <div
                  style={{
                    fontFamily: FONT.sans,
                    fontSize: 12,
                    color: BRAND.stoneLight,
                    marginBottom: 10,
                  } as React.CSSProperties}
                >
                  {campaign.sub}
                </div>

                {/* Stats row */}
                <div style={{ display: "flex", gap: 14, alignItems: "center" } as React.CSSProperties}>
                  {campaign.stats.map((stat, j) => (
                    <div key={j} style={{ display: "flex", flexDirection: "column", gap: 1 } as React.CSSProperties}>
                      <span
                        style={{
                          fontFamily: FONT.sans,
                          fontSize: 9,
                          color: BRAND.stoneLight,
                          textTransform: "uppercase",
                          letterSpacing: "0.06em",
                        } as React.CSSProperties}
                      >
                        {stat.label}
                      </span>
                      <span
                        style={{
                          fontFamily: FONT.sans,
                          fontSize: 13,
                          fontWeight: 600,
                          color: BRAND.onyx,
                        } as React.CSSProperties}
                      >
                        {stat.value}
                      </span>
                    </div>
                  ))}
                  <div style={{ flex: 1 } as React.CSSProperties} />
                  <span
                    style={{
                      fontFamily: FONT.sans,
                      fontSize: 11,
                      fontWeight: 600,
                      color: BRAND.onyx,
                    } as React.CSSProperties}
                  >
                    View &rarr;
                  </span>
                </div>
              </div>
            ))}
          </div>

          {/* Loyalty widget */}
          <div
            style={{
              background: "#FFFFFF",
              border: `1px solid ${BRAND.border}`,
              borderRadius: 10,
              padding: 18,
              marginTop: 14,
            } as React.CSSProperties}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: 14,
              } as React.CSSProperties}
            >
              <span
                style={{
                  fontFamily: FONT.sans,
                  fontSize: 13,
                  fontWeight: 700,
                  color: BRAND.onyx,
                } as React.CSSProperties}
              >
                Loyalty programme &middot; Sable &amp; Sparrow members
              </span>
              <span
                style={{
                  fontFamily: FONT.sans,
                  fontSize: 11,
                  fontWeight: 600,
                  color: BRAND.stoneDark,
                } as React.CSSProperties}
              >
                84 active
              </span>
            </div>

            {loyaltyTiers.map((tier, i) => (
              <div key={i} style={{ marginBottom: i < loyaltyTiers.length - 1 ? 12 : 0 } as React.CSSProperties}>
                <div
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    marginBottom: 5,
                  } as React.CSSProperties}
                >
                  <span
                    style={{
                      fontFamily: FONT.sans,
                      fontSize: 11.5,
                      fontWeight: 500,
                      color: BRAND.stoneDark,
                    } as React.CSSProperties}
                  >
                    {tier.label}
                  </span>
                  <span
                    style={{
                      fontFamily: FONT.mono,
                      fontSize: 11,
                      color: BRAND.stone,
                    } as React.CSSProperties}
                  >
                    {tier.members} members
                  </span>
                </div>
                <div
                  style={{
                    height: 8,
                    background: BRAND.boneDeep,
                    borderRadius: 4,
                    overflow: "hidden",
                  } as React.CSSProperties}
                >
                  <div
                    style={{
                      height: "100%",
                      width: `${tier.pct}%`,
                      background: tier.color,
                      borderRadius: 4,
                    } as React.CSSProperties}
                  />
                </div>
              </div>
            ))}

            <div
              style={{
                fontFamily: FONT.sans,
                fontSize: 11,
                color: BRAND.stoneLight,
                fontStyle: "italic",
                marginTop: 12,
              } as React.CSSProperties}
            >
              Auto-rewards routed via Stripe Connect on next invoice
            </div>
          </div>

          {/* Footer */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              padding: "10px 14px",
              background: BRAND.boneCream,
              borderTop: `1px solid ${BRAND.border}`,
              marginTop: 14,
              borderRadius: "0 0 10px 10px",
            } as React.CSSProperties}
          >
            <span
              style={{
                fontFamily: FONT.sans,
                fontSize: 11,
                color: BRAND.stoneDark,
              } as React.CSSProperties}
            >
              5 live &middot; 2 scheduled &middot; $4,310 attributed revenue this month
            </span>
            <span
              style={{
                fontFamily: FONT.sans,
                fontSize: 11,
                fontWeight: 600,
                color: BRAND.onyx,
              } as React.CSSProperties}
            >
              Open Marketing &rarr;
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}
